        private void CollectLoadID_EnterValidationEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            _LoadID = e.UserInput.ToString();
            if (_LoadID.Trim().Length == 0)
            {
                Error("BlanksNotAllowed");
                return;
            }

            Next(_CollectToBranch);
        }
